make_map<-function(city,model,label){g<-obj$polygons[[which(vapply(obj$polygons,function(x)x$city[1]==city,logical(1)))]];z<-obj$flows[obj$flows$city==city & obj$flows$model==model & obj$flows$displayed,];z<-z[order(z$flow),];bb<-st_bbox(g);dx<-bb['xmax']-bb['xmin'];dy<-bb['ymax']-bb['ymin'];xs<-bb['xmin']+dx*.07;ys<-bb['ymin']+dy*.035;xn<-bb['xmax']-dx*.07;yn<-bb['ymax']-dy*.15
 ggplot()+geom_sf(data=g,aes(fill=observe),color='white',linewidth=.055)+
 geom_segment(data=z,aes(x=x,y=y,xend=xend,yend=yend,color=percentile),linewidth=.045,alpha=.58,lineend='round')+
 scale_fill_manual(name='Observation',values=c(Observed='#737373',Unobserved='#E7E7E7'),limits=c('Observed','Unobserved'),drop=FALSE)+
 scale_color_gradientn(name='Flow percentile (%)',colors=c('#7B1C7A','#E839A5','#FF9ACA','#FFF4D5'),values=c(0,.45,.8,1),limits=c(70,100),breaks=c(70,80,90,100),guide=guide_colorbar(order=2,title.position='top',barwidth=unit(40,'mm'),barheight=unit(2,'mm')))+
 annotate('segment',x=xs,xend=xs+25000,y=ys,yend=ys,linewidth=.55,color='#30343B')+
 annotate('text',x=xs+12500,y=ys-dy*.035,label='25 km',size=7/ggplot2::.pt,family='Arial',vjust=1)+
 annotate('segment',x=xn,xend=xn,y=yn,yend=yn+dy*.07,linewidth=.3,arrow=arrow(type='closed',length=unit(1.3,'mm')),color='#30343B')+
 annotate('text',x=xn,y=yn+dy*.1,label='N',size=7/ggplot2::.pt,family='Arial')+
 coord_sf(crs=st_crs(g),datum=NA,xlim=c(bb['xmin']-dx*.025,bb['xmax']+dx*.025),ylim=c(bb['ymin']-dy*.09,bb['ymax']+dy*.025),expand=FALSE)+
 labs(title=paste(city,'·',model),tag=label)+theme_void(base_family='Arial',base_size=7)+theme(plot.title=element_text(size=8,face='bold',hjust=.5,margin=margin(b=1)),plot.tag=element_text(size=8,face='bold'),plot.tag.position=c(.015,.99),legend.position='bottom',legend.title=element_text(size=7),legend.text=element_text(size=7),legend.key.size=unit(3,'mm'),legend.spacing.x=unit(1,'mm'),plot.margin=margin(1,1,1,1),plot.background=element_rect(fill='white',color=NA),panel.background=element_rect(fill='white',color=NA))
}
